using System;using System.IO;using UnityEditor;using UnityEditor.Build.Player;
[InitializeOnLoad]public static class CityMobileAndroidCompile{static CityMobileAndroidCompile(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityMobileAndroidCompile.request"))return;File.Delete("CityMobileAndroidCompile.request");try{string output="Library/CityMobileAndroidScriptCheck";Directory.CreateDirectory(output);var result=PlayerBuildInterface.CompilePlayerScripts(new ScriptCompilationSettings{target=BuildTarget.Android,group=BuildTargetGroup.Android,options=ScriptCompilationOptions.None},output);if(result.assemblies==null||result.assemblies.Count==0)throw new Exception("Android script compilation produced no assemblies");File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/AndroidCompile.txt","SUCCESS Android release player scripts compiled. Assemblies="+result.assemblies.Count+". This is a script compile check, not an APK build or device performance test.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/AndroidCompile.txt",e.ToString());}}}
